import { useId, useRef, useState } from "react";
import { Button } from "./button";
import { Checkbox } from "./checkbox";
import { Input } from "./input";
import { NativeSelect } from "./native-select";
import { QueryBuilder } from "./query-builder";
import type { QueryField } from "./query-builder";
import { assertWorkViewConfig } from "./work-view";
import type {
    WorkViewColumnOption,
    WorkViewConfig,
    WorkViewPinnedColumns,
    WorkViewSort,
} from "./work-view";

type ViewSettingsPanelProps = {
    columns: readonly WorkViewColumnOption[];
    fields: readonly QueryField[];
    value: WorkViewConfig;
    onValueChange: (value: WorkViewConfig) => void;
    onApply?: (value: WorkViewConfig) => void | Promise<void>;
    disabled?: boolean;
    layouts?: readonly {
        value: NonNullable<WorkViewConfig["layout"]>; label: string;
    }[];
    className?: string;
};

function errorMessage(error: unknown) {
    return error instanceof Error && error.message.trim()
        ? error.message : "보기를 적용하지 못했습니다. 다시 시도하세요.";
}

function ViewSettingsPanel({
    columns, fields, value, onValueChange, onApply, disabled = false,
    className, layouts,
}: ViewSettingsPanelProps) {
    const id = useId();
    const queryBuilderHost = useRef<HTMLDivElement>(null);
    const [pending, setPending] = useState(false);
    const [message, setMessage] = useState<string | null>(null);
    const columnById = new Map(columns.map((column) => [column.id, column]));
    const columnIds = columns.map((column) => column.id);
    const sortableColumns = columns.filter((column) => column.sortable);
    const groupableColumns = columns.filter((column) => column.groupable);

    assertWorkViewConfig(value, columnIds);
    if (columns.some((column) => !column.id.trim() || !column.label.trim()) ||
        columnById.size !== columns.length) {
        throw new Error("ViewSettingsPanel columns need unique IDs and labels.");
    }
    if (fields.some((field) => !columnById.has(field.id))) {
        throw new Error("ViewSettingsPanel filter fields need matching columns.");
    }
    if (fields.length === 0 && value.filter.children.length > 0) {
        throw new Error("ViewSettingsPanel cannot edit filters without fields.");
    }
    if (value.sorts.some((sort) =>
        !columnById.get(sort.columnId)?.sortable,
    )) {
        throw new Error("ViewSettingsPanel cannot edit an unsupported sort.");
    }
    if (value.groupBy && !columnById.get(value.groupBy)?.groupable) {
        throw new Error("ViewSettingsPanel cannot edit an unsupported group.");
    }

    function update(next: WorkViewConfig) {
        setMessage(null);
        onValueChange(next);
    }

    async function apply(next: WorkViewConfig) {
        if (!onApply || disabled || pending) return;
        setPending(true);
        setMessage(null);
        try {
            await onApply(next);
        } catch (error) {
            setMessage(errorMessage(error));
        } finally {
            setPending(false);
        }
    }

    function requestApply() {
        if (fields.length > 0) {
            queryBuilderHost.current?.querySelector("form")?.requestSubmit();
        } else {
            void apply(value);
        }
    }

    function updateSort(
        index: number,
        patch: Partial<WorkViewConfig["sorts"][number]>,
    ) {
        const sorts = value.sorts.map((sort, sortIndex) =>
            sortIndex === index ? { ...sort, ...patch } : sort,
        );
        if (new Set(sorts.map((sort) => sort.columnId)).size !== sorts.length) {
            return;
        }
        update({ ...value, sorts });
    }

    function moveSort(index: number, direction: -1 | 1) {
        const nextIndex = index + direction;
        if (nextIndex < 0 || nextIndex >= value.sorts.length) return;
        const sorts = [...value.sorts];
        [sorts[index], sorts[nextIndex]] = [sorts[nextIndex], sorts[index]];
        update({ ...value, sorts });
    }

    function addSort() {
        const nextColumn = sortableColumns.find((column) =>
            !value.sorts.some((sort) => sort.columnId === column.id),
        );
        if (!nextColumn) return;
        update({
            ...value,
            sorts: [...value.sorts, {
                columnId: nextColumn.id,
                direction: "ascending",
            }],
        });
    }

    function setPin(columnId: string, side: "left" | "right" | "none") {
        const left = value.pinnedColumns.left.filter((id) => id !== columnId);
        const right = value.pinnedColumns.right.filter((id) => id !== columnId);
        if (side === "left") left.push(columnId);
        if (side === "right") right.push(columnId);
        update({ ...value, pinnedColumns: { left, right } });
    }

    return (
        <section data-ui="view-settings-panel" className={className}
            aria-label="보기 설정">
            <div className="grid min-w-0 gap-[var(--space-4)]">
                {layouts && <label className="grid gap-2 text-sm">
                    보기 레이아웃
                    <NativeSelect value={value.layout ?? "table"}
                        disabled={disabled || pending}
                        onChange={(event) => update({ ...value,
                            layout: event.target.value as WorkViewConfig["layout"],
                        })}>
                        {layouts.map((layout) => <option key={layout.value}
                            value={layout.value}>{layout.label}</option>)}
                    </NativeSelect>
                </label>}
                {fields.length > 0 ? (
                    <div ref={queryBuilderHost}>
                        <QueryBuilder
                            label="필터 설정"
                            fields={fields}
                            value={value.filter}
                            onValueChange={(filter) =>
                                update({ ...value, filter })}
                            onApply={onApply ? (filter) =>
                                void apply({ ...value, filter }) : undefined}
                            disabled={disabled || pending}
                        />
                    </div>
                ) : (
                    <p className="m-0 text-sm text-muted">
                        필터를 지원하는 열이 없습니다.
                    </p>
                )}

                <fieldset disabled={disabled || pending}
                    className={"grid min-w-0 gap-2 rounded-sm border " +
                        "border-border p-[var(--space-3)]"}>
                    <legend className="px-1 text-sm font-medium">
                        복수 정렬
                    </legend>
                    <p className="m-0 text-sm text-muted">
                        위쪽 규칙부터 적용합니다.
                    </p>
                    {value.sorts.map((sort, index) => (
                        <div key={`${sort.columnId}-${index}`}
                            className="flex min-w-0 flex-wrap items-center gap-2">
                            <span className="text-sm text-muted">
                                {index + 1}순위
                            </span>
                            <NativeSelect
                                aria-label={`${index + 1}순위 정렬 열`}
                                value={sort.columnId}
                                onChange={(event) => updateSort(index, {
                                    columnId: event.target.value,
                                })}>
                                {sortableColumns.map((column) => (
                                    <option key={column.id} value={column.id}
                                        disabled={value.sorts.some((other,
                                            otherIndex) =>
                                            otherIndex !== index &&
                                            other.columnId === column.id)}>
                                        {column.label}
                                    </option>
                                ))}
                            </NativeSelect>
                            <NativeSelect
                                aria-label={`${index + 1}순위 정렬 방향`}
                                value={sort.direction}
                                onChange={(event) => updateSort(index, {
                                    direction: event.target.value as
                                        "ascending" | "descending",
                                })}>
                                <option value="ascending">오름차순</option>
                                <option value="descending">내림차순</option>
                            </NativeSelect>
                            <Button variant="ghost"
                                aria-label={`${index + 1}순위 위로 이동`}
                                disabled={index === 0}
                                onClick={() => moveSort(index, -1)}>
                                위로
                            </Button>
                            <Button variant="ghost"
                                aria-label={`${index + 1}순위 아래로 이동`}
                                disabled={index === value.sorts.length - 1}
                                onClick={() => moveSort(index, 1)}>
                                아래로
                            </Button>
                            <Button variant="ghost"
                                aria-label={`${index + 1}순위 정렬 제거`}
                                onClick={() => update({
                                    ...value,
                                    sorts: value.sorts.filter((_, sortIndex) =>
                                        sortIndex !== index,
                                    ),
                                })}>
                                제거
                            </Button>
                        </div>
                    ))}
                    {sortableColumns.length > value.sorts.length && (
                        <Button variant="outline" className="w-fit"
                            onClick={addSort}>
                            정렬 추가
                        </Button>
                    )}
                    {sortableColumns.length === 0 && (
                        <p className="m-0 text-sm text-muted">
                            정렬할 수 있는 열이 없습니다.
                        </p>
                    )}
                </fieldset>

                <fieldset disabled={disabled || pending}
                    className={"grid min-w-0 gap-2 rounded-sm border " +
                        "border-border p-[var(--space-3)]"}>
                    <legend className="px-1 text-sm font-medium">그룹</legend>
                    <label htmlFor={`${id}-group`} className="sr-only">
                        그룹 열
                    </label>
                    <NativeSelect id={`${id}-group`} value={value.groupBy ?? ""}
                        onChange={(event) => update({
                            ...value,
                            groupBy: event.target.value || null,
                        })}>
                        <option value="">그룹 없음</option>
                        {groupableColumns.map((column) => (
                            <option key={column.id} value={column.id}>
                                {column.label}
                            </option>
                        ))}
                    </NativeSelect>
                    {groupableColumns.length === 0 && (
                        <p className="m-0 text-sm text-muted">
                            그룹으로 묶을 수 있는 열이 없습니다.
                        </p>
                    )}
                </fieldset>

                <fieldset disabled={disabled || pending}
                    className={"grid min-w-0 gap-2 rounded-sm border " +
                        "border-border p-[var(--space-3)]"}>
                    <legend className="px-1 text-sm font-medium">열 설정</legend>
                    <div className="grid min-w-0 gap-2">
                        {value.columnOrder.map((columnId, index) => {
                            const column = columnById.get(columnId)!;
                            const pinned = value.pinnedColumns.left.includes(
                                columnId,
                            ) ? "left" :
                                value.pinnedColumns.right.includes(columnId)
                                    ? "right" : "none";
                            const isVisible = value.visibleColumns.includes(
                                columnId,
                            );
                            const width = value.columnWidths[columnId] ?? 180;
                            return (
                                <div key={columnId}
                                    className={"grid min-w-0 gap-2 rounded-sm " +
                                        "border border-border bg-surface p-2 " +
                                        "sm:grid-cols-[minmax(0,1fr)_auto_auto_auto] " +
                                        "sm:items-center"}>
                                    <label className="flex min-w-0 items-center gap-2">
                                        <Checkbox
                                            aria-label={`${column.label} 표시`}
                                            checked={isVisible}
                                            disabled={isVisible &&
                                                value.visibleColumns.length === 1}
                                            onCheckedChange={(checked) => {
                                                const visibleColumns = checked === true
                                                    ? [...value.visibleColumns,
                                                        columnId]
                                                    : value.visibleColumns.filter(
                                                        (id) => id !== columnId,
                                                    );
                                                update({ ...value,
                                                    visibleColumns });
                                            }}
                                        />
                                        <span className="truncate text-sm">
                                            {column.label}
                                        </span>
                                        <span className="text-xs text-muted">
                                            {index + 1}순서
                                        </span>
                                    </label>
                                    <div className="flex gap-1">
                                        <Button variant="ghost"
                                            aria-label={`${column.label} 앞쪽으로 이동`}
                                            disabled={index === 0}
                                            onClick={() => {
                                                const columnOrder = [
                                                    ...value.columnOrder,
                                                ];
                                                [columnOrder[index - 1],
                                                    columnOrder[index]] =
                                                    [columnOrder[index],
                                                        columnOrder[index - 1]];
                                                update({ ...value, columnOrder });
                                            }}>
                                            위
                                        </Button>
                                        <Button variant="ghost"
                                            aria-label={`${column.label} 뒤쪽으로 이동`}
                                            disabled={index ===
                                                value.columnOrder.length - 1}
                                            onClick={() => {
                                                const columnOrder = [
                                                    ...value.columnOrder,
                                                ];
                                                [columnOrder[index],
                                                    columnOrder[index + 1]] =
                                                    [columnOrder[index + 1],
                                                        columnOrder[index]];
                                                update({ ...value, columnOrder });
                                            }}>
                                            아래
                                        </Button>
                                    </div>
                                    <label className="flex items-center gap-2 text-sm">
                                        <span className="text-muted">너비</span>
                                        <Input type="number" min={48} max={1200}
                                            aria-label={`${column.label} 너비`}
                                            className="w-24"
                                            value={String(width)}
                                            onChange={(event) => {
                                                const next = Number(
                                                    event.target.value,
                                                );
                                                if (Number.isInteger(next) &&
                                                    next >= 48 && next <= 1200) {
                                                    update({ ...value,
                                                        columnWidths: {
                                                            ...value.columnWidths,
                                                            [columnId]: next,
                                                        },
                                                    });
                                                }
                                            }} />
                                    </label>
                                    <label className="flex items-center gap-2 text-sm">
                                        <span className="text-muted">고정</span>
                                        <NativeSelect
                                            aria-label={`${column.label} 고정 위치`}
                                            value={pinned}
                                            onChange={(event) => setPin(
                                                columnId,
                                                event.target.value as
                                                    "left" | "right" | "none",
                                            )}>
                                            <option value="none">없음</option>
                                            <option value="left">왼쪽</option>
                                            <option value="right">오른쪽</option>
                                        </NativeSelect>
                                    </label>
                                </div>
                            );
                        })}
                    </div>
                </fieldset>

                {onApply && <Button variant="primary" disabled={
                    disabled || pending
                } onClick={requestApply}>
                    {pending ? "적용 중…" : "보기 적용"}
                </Button>}
                {message && <p role="alert" className="m-0 text-sm text-danger">
                    {message}
                </p>}
            </div>
        </section>
    );
}

export { ViewSettingsPanel };
export type {
    ViewSettingsPanelProps,
    QueryField,
    WorkViewColumnOption,
    WorkViewConfig,
    WorkViewPinnedColumns,
    WorkViewSort,
};
